{
  "name": "JLCEDA Pro",
  "summary": "",
  "children": [
    {
      "path": "activate",
      "summary": "Bring the server window up and focus it"
    },
    {
      "path": "open",
      "summary": "Open a project and return its session id; .eprj3 folder projects stay in two-way sync with the editor (disk edits reload automatically, editor saves land on disk automatically); without --path open a bare editor (visible window; --headless for a hidden render)"
    },
    {
      "path": "stop",
      "summary": "Gracefully stop the server"
    },
    {
      "path": "doctor",
      "summary": "Probe the endpoint and report its identity"
    },
    {
      "path": "session",
      "summary": "List sessions (each with origin cli/user, the project path and the window title)"
    },
    {
      "path": "invoke",
      "summary": "Invoke a registered function by extension id + name (source runs on the editor command space; omit extUuid to run with independent script permission). ok:true means the code ran, not that the operation succeeded"
    },
    {
      "path": "functions",
      "summary": "List extensions known to the session (editor command space extension index)"
    },
    {
      "path": "doc",
      "summary": "Query the eda namespace (static editor API) progressively (surface / class / method)"
    }
  ]
}
